import { useState } from "react";
function ShoppingItem({ item }) {
  const handleDelete = (id) => {
    console.log(id);
  };
  return (
    <li>
      {item.text}
      <button className="btn-remove">
        <i
          className="fa-solid fa-xmark"
          onClick={() => handleDelete(item.id)}
        ></i>
      </button>
    </li>
  );
}

export default ShoppingItem;
